import heapq
class Solution:
    def nthSuperUglyNumber(self, n: int, primes: List[int]) -> int:
        heap = [1]
        seen = {1}
        for _ in range(n - 1):
            cur = heapq.heappop(heap)
            for p in primes:
                v = cur * p
                if v not in seen:
                    seen.add(v)
                    heapq.heappush(heap, v)
        return heap[0]

