class Solution {
    public int nthSuperUglyNumber(int n, int[] primes) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        Set<Long> seen = new HashSet<>();
        pq.offer(1L); seen.add(1L);
        for (int i = 1; i < n; i++) {
            long cur = pq.poll();
            for (int p : primes) {
                long v = cur * p;
                if (seen.add(v)) pq.offer(v);
            }
        }
        return pq.peek().intValue();
    }
}

