    const seen = new Set([1]);
    heap.enqueue(1, 1);
    for (let i = 1; i < n; i++) {
        const cur = heap.dequeue().element;
        for (const p of primes) {
            const v = cur * p;
            if (!seen.has(v)) { seen.add(v); heap.enqueue(v, v); }
        }
    }
