        ugly[0] = 1
        m = len(primes)
        idx = [0] * m
        for k in range(1, n):
            best = min(ugly[idx[i]] * primes[i] for i in range(m))
            ugly[k] = best
            for i in range(m):
                if ugly[idx[i]] * primes[i] == best:
                    idx[i] += 1
        return ugly[n - 1]

